const input = $json || {};
const clean = (value, fallback, label) => {
  const text = String(value ?? fallback ?? '').trim();
  if (!text || !/^[A-Za-z0-9._:-]+$/.test(text)) throw new Error(label + ' contains unsupported characters');
  return text;
};
const action = String(input.action || 'create').trim().toLowerCase();
if (!['create', 'update'].includes(action)) throw new Error('action must be create or update');
const runId = clean(input.incremental_run_id, 'phase9c35-' + String($execution.id), 'incremental_run_id');
const planId = clean(input.plan_id, 'manual-shadow-plan', 'plan_id');
const collectionName = clean(input.collection_name, 'tpm_unite_history', 'collection_name');
const n8nExecutionId = clean($execution.id, '', 'n8n_execution_id');
const payload = {
  phase: '9C.3.5',
  action,
  requested_by: String(input.requested_by || 'developer').slice(0, 200),
  simulation: true,
  qdrant_mutations: 0,
  pending_work_claimed: 0
};
return [{ json: {
  action,
  incremental_run_id: runId,
  plan_id: planId,
  collection_name: collectionName,
  n8n_execution_id: n8nExecutionId,
  run_data_sql: JSON.stringify(payload).replace(/'/g, "''"),
  phoenix_collector_url: $env.TRACE_EMITTER_URL || 'http://trace-emitter:8001/v1/traces',
  phoenix_project_name: 'discord-rag-bot-phase-9c35'
} }];

