let dbState;
try { dbState = $items('Update Durable Run')[0]?.json; } catch (error) { dbState = null; }
if (!dbState) dbState = $items('Create Or Read Durable Run')[0].json;
const command = $items('Normalize Coordinator Command')[0].json;
return [{ json: {
  ...dbState,
  action: command.action,
  plan_id: command.plan_id,
  collection_name: command.collection_name,
  n8n_execution_id: command.n8n_execution_id,
  phoenix_collector_url: command.phoenix_collector_url,
  phoenix_project_name: command.phoenix_project_name,
  postgres_authoritative: true,
  qdrant_mutations: 0,
  pending_work_claimed: 0
} }];

const state = $json || {};
function bytesToBase64(bytes) { let binary = ''; for (const byte of bytes) binary += String.fromCharCode(byte); return btoa(binary); }
function hashBytes(text, size) { let a = 2166136261 >>> 0; let b = 2246822519 >>> 0; for (let i = 0; i < text.length; i++) { a = Math.imul(a ^ text.charCodeAt(i), 16777619) >>> 0; b = Math.imul(b ^ (text.charCodeAt(i) + i), 3266489917) >>> 0; } const out = []; for (let i = 0; i < size; i++) { a = Math.imul(a ^ (a >>> 13), 16777619) >>> 0; b = Math.imul(b ^ (b >>> 16), 2246822519) >>> 0; out.push((a ^ b ^ (i * 31)) & 255); } return out; }
function value(v) { if (typeof v === 'boolean') return { boolValue: v }; if (typeof v === 'number') return Number.isInteger(v) ? { intValue: String(v) } : { doubleValue: v }; return { stringValue: String(v ?? '') }; }
function attrs(values) { return Object.entries(values).map(([key, val]) => ({ key, value: value(val) })); }
const nowNs = String(Date.now() * 1000000);
const traceId = bytesToBase64(hashBytes(String(state.incremental_run_id), 16));
const spanId = bytesToBase64(hashBytes(String(state.incremental_run_id) + ':' + String(state.runtime_revision), 8));
const span = {
  traceId,
  spanId,
  name: 'incremental.lifecycle_coordinated',
  kind: 1,
  startTimeUnixNano: nowNs,
  endTimeUnixNano: nowNs,
  attributes: attrs({
    incremental_run_id: state.incremental_run_id,
    action: state.action,
    plan_id: state.plan_id,
    collection_name: state.collection_name,
    run_state: state.run_state,
    runtime_state: state.runtime_state,
    runtime_revision: state.runtime_revision,
    n8n_execution_id: state.n8n_execution_id,
    postgres_authoritative: true,
    qdrant_mutations: 0,
    pending_work_claimed: 0
  }),
  status: { code: 1 }
};
const payload = { resourceSpans: [{ resource: { attributes: attrs({ 'service.name': 'discord-rag-bot', 'deployment.environment': 'phase0', 'phoenix.project.name': state.phoenix_project_name }) }, scopeSpans: [{ scope: { name: 'n8n.phase9c35.coordinator', version: '1.0.0' }, spans: [span] }] }] };
return [{ json: { ...state, phoenix_trace_payload: payload, phoenix_trace_id: traceId } }];

const state = $items('Build Correlated Phoenix Span')[0].json;
const { phoenix_trace_payload, ...result } = state;
return [{ json: { ...result, trace_delivery_best_effort: true, coordinator_workflow: 'RAG Incremental Coordinator - Phase 9C.3.5' } }];
